fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Calculate number of turns as ceiling(health / strength)
    ((health as i64 + strength as i64 - 1) / strength as i64)
}

fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    let takahashi_turns = exec_turns_to_defeat(c, b); // Takahashi must reduce Aoki's health c with attack b
    let aoki_turns = exec_turns_to_defeat(a, d);     // Aoki must reduce Takahashi's health a with attack d

    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

